class UnionFind:
    def __init__(self, N):
        self.p = list(range(N))

    def change(self, i, val):
        val = max(val, self.find(i))
        if self.find(val) == self.find(i):
            self.p[i] = val

    def find(self, i):
        if self.p[i]!= i:
            self.p[i] = self.find(self.p[i])
        return self.p[i]


def f(N: int, members: List[Tuple[str, int]], M: int, changes: List[str]):
    uf = UnionFind(N)
    seen_changes = set()

    for s, a in members:
        if s not in seen_changes:
            uf.change(a, s)
            seen_changes.add(s)

    for change in changes:
        if change not in seen_changes and change!= "+ t b":
            uf.change(int(change.split()[1]), change.split()[0])

    return len(list(set(sp[0] for sp in uf.p)))

